     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_wse_ffi_fn_clone_wsecancel(handle, status)
        }
    }

    override fun `cancel`()
        =
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_wse_ffi_fn_method_wsecancel_cancel(
        it,
        _status)
}
    }



    override fun `isCancelled`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_wse_ffi_fn_method_wsecancel_is_cancelled(
        it,
        _status)
}
    }
    )
