    ,
    val `topic`: kotlin.String?
    ,
    val `epoch`: kotlin.UInt?
    ,
    val `offset`: kotlin.ULong?
    ,
    val `id`: kotlin.String?
    ,
    /**
     * The payload as JSON text (from msgpack too); None without one
     * (absent or null) or when it could not be decoded.
     */
    val `json`: kotlin.String?
    ,
    /**
     * Why the payload could not be decoded (msgpack JSON cannot show).
     */
    val `payloadError`: kotlin.String?
    ,
    val `signature`: WseSignature?
    ,
    /**
     * The user generation it was handed out in: a new one starts where
     * the events show another user. `commit` takes it back.
     */
    val `generation`: kotlin.UInt

){





    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeWseMessage: FfiConverterRustBuffer<WseMessage> {
    override fun read(buf: ByteBuffer): WseMessage {
        return WseMessage(
            FfiConverterString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalUInt.read(buf),
            FfiConverterOptionalULong.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterOptionalTypeWseSignature.read(buf),
            FfiConverterUInt.read(buf),
        )
    }

    override fun allocationSize(value: WseMessage) = (
            FfiConverterString.allocationSize(value.`kind`) +
            FfiConverterOptionalString.allocationSize(value.`topic`) +
            FfiConverterOptionalUInt.allocationSize(value.`epoch`) +
            FfiConverterOptionalULong.allocationSize(value.`offset`) +
            FfiConverterOptionalString.allocationSize(value.`id`) +
            FfiConverterOptionalString.allocationSize(value.`json`) +
            FfiConverterOptionalString.allocationSize(value.`payloadError`) +
            FfiConverterOptionalTypeWseSignature.allocationSize(value.`signature`) +
            FfiConverterUInt.allocationSize(value.`generation`)
    )

    override fun write(value: WseMessage, buf: ByteBuffer) {
            FfiConverterString.write(value.`kind`, buf)
            FfiConverterOptionalString.write(value.`topic`, buf)
            FfiConverterOptionalUInt.write(value.`epoch`, buf)
            FfiConverterOptionalULong.write(value.`offset`, buf)
            FfiConverterOptionalString.write(value.`id`, buf)
            FfiConverterOptionalString.write(value.`json`, buf)
            FfiConverterOptionalString.write(value.`payloadError`, buf)
            FfiConverterOptionalTypeWseSignature.write(value.`signature`, buf)
            FfiConverterUInt.write(value.`generation`, buf)
    }
}



/**
 * Messages sent with no connection, kept for the next one of the same user. They go right
 * after the topics are subscribed again; a live or signed message is never kept.
 */
data class WseOffline (
    /**
     * The file they are kept in, so that they outlive the app (in its own storage); the
     * client's alone while it runs. None keeps them in memory.
     */
    val `path`: kotlin.String? = null
    ,
    /**
     * How many are kept at most (0: 1,000); past it a send fails as `Full`.
     */
    val `maxMessages`: kotlin.UInt = 0u
    ,
    /**
     * How long one is kept, in milliseconds (0: an hour); an older one is dropped.
     */
    val `maxAgeMs`: kotlin.ULong = 0uL

){





    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeWseOffline: FfiConverterRustBuffer<WseOffline> {
    override fun read(buf: ByteBuffer): WseOffline {
        return WseOffline(
            FfiConverterOptionalString.read(buf),
            FfiConverterUInt.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: WseOffline) = (
            FfiConverterOptionalString.allocationSize(value.`path`) +
            FfiConverterUInt.allocationSize(value.`maxMessages`) +
            FfiConverterULong.allocationSize(value.`maxAgeMs`)
    )

    override fun write(value: WseOffline, buf: ByteBuffer) {
            FfiConverterOptionalString.write(value.`path`, buf)
            FfiConverterUInt.write(value.`maxMessages`, buf)
            FfiConverterULong.write(value.`maxAgeMs`, buf)
    }
}



