enum class WseBatchKind {

    ITEMS,
    /**
     * Nothing more will come: the client closed.
     */
    END;




    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeWseBatchKind: FfiConverterRustBuffer<WseBatchKind> {
    override fun read(buf: ByteBuffer) = try {
        WseBatchKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: WseBatchKind) = 4UL

    override fun write(value: WseBatchKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





