/**
 * What went wrong. A kind added later reads as `Unknown`.
 */
sealed class WseException: kotlin.Exception() {

    class Config(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Connect(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Auth(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Timeout(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Encryption(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Signing(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class GaveUp(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class NotConnected(
        ) : WseException() {
        override val message
            get() = ""
    }

    class Full(
        ) : WseException() {
        override val message
            get() = ""
    }

    class Closed(
        ) : WseException() {
        override val message
            get() = ""
    }

    class Encode(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Decode(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Cancelled(
        ) : WseException() {
        override val message
            get() = ""
    }

    class Busy(
        ) : WseException() {
        override val message
            get() = ""
    }

    class Internal(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }

    class Unknown(

        val `reason`: kotlin.String
        ) : WseException() {
        override val message
            get() = "reason=${ `reason` }"
    }





    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<WseException> {
        override fun lift(error_buf: RustBuffer.ByValue): WseException = FfiConverterTypeWseError.lift(error_buf)
    }


}

/**
 * @suppress
 */
public object FfiConverterTypeWseError : FfiConverterRustBuffer<WseException> {
    override fun read(buf: ByteBuffer): WseException {


        return when(buf.getInt()) {
            1 -> WseException.Config(
                FfiConverterString.read(buf),
                )
            2 -> WseException.Connect(
                FfiConverterString.read(buf),
                )
            3 -> WseException.Auth(
                FfiConverterString.read(buf),
                )
            4 -> WseException.Timeout(
                FfiConverterString.read(buf),
                )
            5 -> WseException.Encryption(
                FfiConverterString.read(buf),
                )
            6 -> WseException.Signing(
                FfiConverterString.read(buf),
                )
            7 -> WseException.GaveUp(
                FfiConverterString.read(buf),
                )
            8 -> WseException.NotConnected()
            9 -> WseException.Full()
            10 -> WseException.Closed()
            11 -> WseException.Encode(
                FfiConverterString.read(buf),
                )
            12 -> WseException.Decode(
                FfiConverterString.read(buf),
                )
            13 -> WseException.Cancelled()
            14 -> WseException.Busy()
            15 -> WseException.Internal(
                FfiConverterString.read(buf),
                )
            16 -> WseException.Unknown(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WseException): ULong {
        return when(value) {
            is WseException.Config -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
