                Unit
            }
            is WseException.Unknown -> {
                buf.putInt(16)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * One thing the client heard, in order.
 */
sealed class WseItem {

    data class Message(
        val `message`: dev.wse.ffi.WseMessage) : WseItem()

    {


        companion object
    }

    data class Binary(
        val `bytes`: kotlin.ByteArray) : WseItem()

    {


        companion object
    }

    data class Connected(
        val `connectionId`: kotlin.String,
        val `userId`: kotlin.String?,
        val `reconnected`: kotlin.Boolean,
        val `recovery`: kotlin.Boolean) : WseItem()

    {


        companion object
    }

    data class Disconnected(
        val `code`: kotlin.UShort?,
        val `reason`: kotlin.String,
        val `retryInMs`: kotlin.ULong,
        val `attempt`: kotlin.UInt) : WseItem()

    {


        companion object
    }

    /**
     * Paused by the application: no connection until the last reason is
     * cleared; topics and positions stay.
     */
    data class Paused(
        val `reasons`: List<kotlin.String>) : WseItem()

    {


        companion object
    }

    data class Subscribed(
        val `topics`: List<kotlin.String>,
        val `failed`: List<kotlin.String>,
        val `recovery`: List<dev.wse.ffi.WseTopicRecovery>) : WseItem()

    {


        companion object
    }

    /**
     * Messages of a topic that will not come: reload what depends on them.
     */
    data class Gap(
        val `topic`: kotlin.String,
        val `epoch`: kotlin.UInt,
        val `first`: kotlin.ULong?,
        val `last`: kotlin.ULong?,
        val `reason`: kotlin.String) : WseItem()

    {


        companion object
    }

    data class ServerError(
        val `code`: kotlin.String,
        val `text`: kotlin.String,
        val `detailsJson`: kotlin.String) : WseItem()

    {


        companion object
    }

    /**
     * The client stopped for good; `reason` when it was not closed by the application.
     */
    data class Closed(
        val `reason`: kotlin.String?) : WseItem()

    {


        companion object
    }

    /**
     * recover-or-resync: bring the state of `topics` up to date (the
     * reason of each, what the consumer committed), then call
     * `resynced(round)`; their messages wait till then.
     */
    data class Resync(
        val `round`: kotlin.ULong,
        val `topics`: List<kotlin.String>,
        val `reasons`: List<kotlin.String>,
        val `committed`: List<dev.wse.ffi.WseStreamPosition>) : WseItem()

    {


        companion object
    }

    /**
     * A topic's continuity changed, and why it is not continuous.
     */
    data class Continuity(
        val `topic`: kotlin.String,
        val `continuity`: dev.wse.ffi.WseContinuity,
        val `reason`: kotlin.String?) : WseItem()

    {


        companion object
    }

    /**
     * The saved checkpoint is not this client's: its realm, user,
     * consumer, schema or version, or it is malformed.
     */
    data class CheckpointRejected(
        val `reason`: kotlin.String) : WseItem()

    {


        companion object
    }

    /**
     * The offline queue's file could not be written (`operation`): what is kept stays in
     * memory, and may not outlive the app.
     */
    data class StorageFailed(
        val `operation`: kotlin.String,
        val `message`: kotlin.String) : WseItem()

    {


        companion object
    }

    /**
     * Something this version does not know.
     */
    data class Unknown(
        val `name`: kotlin.String) : WseItem()

    {


        companion object
    }








    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeWseItem : FfiConverterRustBuffer<WseItem>{
    override fun read(buf: ByteBuffer): WseItem {
        return when(buf.getInt()) {
            1 -> WseItem.Message(
                FfiConverterTypeWseMessage.read(buf),
                )
            2 -> WseItem.Binary(
                FfiConverterByteArray.read(buf),
                )
            3 -> WseItem.Connected(
                FfiConverterString.read(buf),
                FfiConverterOptionalString.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                )
            4 -> WseItem.Disconnected(
                FfiConverterOptionalUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                FfiConverterUInt.read(buf),
                )
            5 -> WseItem.Paused(
                FfiConverterSequenceString.read(buf),
                )
            6 -> WseItem.Subscribed(
                FfiConverterSequenceString.read(buf),
                FfiConverterSequenceString.read(buf),
                FfiConverterSequenceTypeWseTopicRecovery.read(buf),
                )
            7 -> WseItem.Gap(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterOptionalULong.read(buf),
                FfiConverterString.read(buf),
                )
            8 -> WseItem.ServerError(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            9 -> WseItem.Closed(
                FfiConverterOptionalString.read(buf),
                )
            10 -> WseItem.Resync(
                FfiConverterULong.read(buf),
                FfiConverterSequenceString.read(buf),
                FfiConverterSequenceString.read(buf),
                FfiConverterSequenceTypeWseStreamPosition.read(buf),
                )
            11 -> WseItem.Continuity(
                FfiConverterString.read(buf),
                FfiConverterTypeWseContinuity.read(buf),
                FfiConverterOptionalString.read(buf),
                )
            12 -> WseItem.CheckpointRejected(
                FfiConverterString.read(buf),
                )
            13 -> WseItem.StorageFailed(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            14 -> WseItem.Unknown(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WseItem): ULong = when(value) {
        is WseItem.Message -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeWseMessage.allocationSize(value.`message`)
            )
        }
        is WseItem.Binary -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterByteArray.allocationSize(value.`bytes`)
            )
        }
        is WseItem.Connected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`connectionId`)
                + FfiConverterOptionalString.allocationSize(value.`userId`)
                + FfiConverterBoolean.allocationSize(value.`reconnected`)
                + FfiConverterBoolean.allocationSize(value.`recovery`)
            )
        }
        is WseItem.Disconnected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalUShort.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterULong.allocationSize(value.`retryInMs`)
                + FfiConverterUInt.allocationSize(value.`attempt`)
            )
        }
        is WseItem.Paused -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`reasons`)
            )
        }
        is WseItem.Subscribed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterSequenceString.allocationSize(value.`topics`)
                + FfiConverterSequenceString.allocationSize(value.`failed`)
                + FfiConverterSequenceTypeWseTopicRecovery.allocationSize(value.`recovery`)
            )
        }
        is WseItem.Gap -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`topic`)
                + FfiConverterUInt.allocationSize(value.`epoch`)
                + FfiConverterOptionalULong.allocationSize(value.`first`)
                + FfiConverterOptionalULong.allocationSize(value.`last`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is WseItem.ServerError -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`text`)
                + FfiConverterString.allocationSize(value.`detailsJson`)
            )
        }
        is WseItem.Closed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterOptionalString.allocationSize(value.`reason`)
            )
        }
        is WseItem.Resync -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`round`)
                + FfiConverterSequenceString.allocationSize(value.`topics`)
                + FfiConverterSequenceString.allocationSize(value.`reasons`)
                + FfiConverterSequenceTypeWseStreamPosition.allocationSize(value.`committed`)
            )
        }
        is WseItem.Continuity -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`topic`)
                + FfiConverterTypeWseContinuity.allocationSize(value.`continuity`)
                + FfiConverterOptionalString.allocationSize(value.`reason`)
            )
        }
        is WseItem.CheckpointRejected -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
        is WseItem.StorageFailed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`operation`)
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
        is WseItem.Unknown -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
    }

    override fun write(value: WseItem, buf: ByteBuffer) {
        when(value) {
            is WseItem.Message -> {
                buf.putInt(1)
                FfiConverterTypeWseMessage.write(value.`message`, buf)
                Unit
            }
            is WseItem.Binary -> {
                buf.putInt(2)
                FfiConverterByteArray.write(value.`bytes`, buf)
                Unit
            }
            is WseItem.Connected -> {
                buf.putInt(3)
                FfiConverterString.write(value.`connectionId`, buf)
                FfiConverterOptionalString.write(value.`userId`, buf)
                FfiConverterBoolean.write(value.`reconnected`, buf)
                FfiConverterBoolean.write(value.`recovery`, buf)
                Unit
            }
            is WseItem.Disconnected -> {
                buf.putInt(4)
                FfiConverterOptionalUShort.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterULong.write(value.`retryInMs`, buf)
                FfiConverterUInt.write(value.`attempt`, buf)
                Unit
            }
            is WseItem.Paused -> {
                buf.putInt(5)
                FfiConverterSequenceString.write(value.`reasons`, buf)
                Unit
            }
            is WseItem.Subscribed -> {
                buf.putInt(6)
                FfiConverterSequenceString.write(value.`topics`, buf)
                FfiConverterSequenceString.write(value.`failed`, buf)
                FfiConverterSequenceTypeWseTopicRecovery.write(value.`recovery`, buf)
                Unit
            }
            is WseItem.Gap -> {
                buf.putInt(7)
                FfiConverterString.write(value.`topic`, buf)
                FfiConverterUInt.write(value.`epoch`, buf)
                FfiConverterOptionalULong.write(value.`first`, buf)
                FfiConverterOptionalULong.write(value.`last`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is WseItem.ServerError -> {
                buf.putInt(8)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterString.write(value.`detailsJson`, buf)
                Unit
            }
            is WseItem.Closed -> {
                buf.putInt(9)
                FfiConverterOptionalString.write(value.`reason`, buf)
                Unit
            }
            is WseItem.Resync -> {
                buf.putInt(10)
                FfiConverterULong.write(value.`round`, buf)
                FfiConverterSequenceString.write(value.`topics`, buf)
                FfiConverterSequenceString.write(value.`reasons`, buf)
                FfiConverterSequenceTypeWseStreamPosition.write(value.`committed`, buf)
                Unit
            }
            is WseItem.Continuity -> {
                buf.putInt(11)
                FfiConverterString.write(value.`topic`, buf)
                FfiConverterTypeWseContinuity.write(value.`continuity`, buf)
                FfiConverterOptionalString.write(value.`reason`, buf)
                Unit
            }
            is WseItem.CheckpointRejected -> {
                buf.putInt(12)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is WseItem.StorageFailed -> {
                buf.putInt(13)
                FfiConverterString.write(value.`operation`, buf)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is WseItem.Unknown -> {
                buf.putInt(14)
                FfiConverterString.write(value.`name`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






